@Service
public class ConditionService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public ConditionService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ConditionEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ConditionRepository.class) );
		this.validator		= applicationContext.getBean(ConditionValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Condition
	 */
		public Condition createCondition( CreateConditionCommand command ) {

		Condition entity = new Condition();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setConditionId( command.getConditionId() );
            entity.setCode( command.getCode() );
            entity.setOnsetDate( command.getOnsetDate() );
            entity.setAbatementDate( command.getAbatementDate() );
            entity.setClinicalStatus( command.getClinicalStatus() );
            entity.setVerificationStatus( command.getVerificationStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Condition {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateConditionCommand
	 * @return		Condition
	 */
	public Condition updateCondition( UpdateConditionCommand command ) {

		Condition entity = new Condition();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setConditionId( command.getConditionId() );
            entity.setCode( command.getCode() );
            entity.setOnsetDate( command.getOnsetDate() );
            entity.setAbatementDate( command.getAbatementDate() );
            entity.setPatient( command.getPatient() );
            entity.setClinicalStatus( command.getClinicalStatus() );
            entity.setVerificationStatus( command.getVerificationStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Condition {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteConditionCommand
	 */
	public void delete( DeleteConditionCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getConditionId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Condition {0} ", id );

	}

	/**
	 * Method to retrieve the Condition via ConditionFetchOneSummary
	 * @param 	summary ConditionFetchOneSummary
	 * @return 	ConditionFetchOneResponse
	 */
	public Condition getCondition( ConditionFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ConditionFetchOneSummary arg cannot be null" );

		Condition entity = null;
		UUID id = summary.getConditionId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Condition using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Conditions
	 *
	 * @return 	List<Condition>
	 */
    public List<Condition> getAllCondition() {
		List<Condition> list = projector.findAll( new FindAllConditionQuery() );
		return list;
	}

	/**
	 * assign Patient on Condition
	 * @param		command AssignPatientToConditionCommand
	 */
	public void assignPatient( AssignPatientToConditionCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPatient(command.getConditionId(), command.getAssignment());

	}

	/**
	 * unAssign Patient on Condition
	 * @param		command UnAssignPatientFromConditionCommand
	 */
	public void unAssignPatient( UnAssignPatientFromConditionCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignPatient(command.getConditionId());
	}
	




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final ConditionEntityProjector projector;
	private final ConditionValidator validator;
	private Condition condition 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(ConditionService.class);
}
